<script setup>
import {computed} from 'vue'
import MetricBar from './MetricBar.vue'
import SparkChart from './SparkChart.vue'
import {bytes,percent,isOnline,price,probeLines} from '../utils/metrics.js'
import {t,options} from '../composables/useTheme.js'
import {pageState} from '../composables/useMonitor.js'
const props=defineProps({server:Object,site:Object})
const online=computed(()=>isOnline(props.server,pageState.now))
const cardPrice=computed(()=>price(props.server))
const lineSeries=computed(()=>probeLines(props.site.config).slice(0,4))
const osFile=computed(()=>{const os=String(props.server.os||'').toLowerCase(); const known=['ubuntu','debian','alpine','windows','centos','fedora','arch','macos','openwrt','rocky','redhat','oracle','gentoo','mint','nix','alma'].find(s=>os.includes(s));return known==='alpine'?'os-alpine.webp':`os-${known || 'unknown'}.svg`})
</script>
<template><article class="server-card panel"><div class="card-heading"><div class="server-identity"><img v-if="server.region && /^[a-z]{2}$/i.test(server.region)" class="flag" :src="`${site.base}/flags/${server.region.toLowerCase()}.svg`" :alt="server.region"><div><RouterLink :to="{path:'/server/'+encodeURIComponent(server.id),query:site.index ? {site:site.index} : {}}" class="server-name">{{server.name || server.id}} <span>↗</span></RouterLink><p class="muted card-subtitle">{{server.server_group || server.region || '—'}} <span v-if="server.cpu_cores">· {{server.cpu_cores}} {{t('核','cores')}}</span></p></div></div><span class="status-chip" :class="{online}"><i></i>{{online?t('在线','Online'):t('离线','Offline')}}</span></div><div class="card-metrics"><MetricBar label="CPU" :value="typeof server.cpu==='number'?server.cpu:null"/><MetricBar :label="t('内存','Memory')" :value="percent(server.ram_used,server.ram_total)" :caption="`${bytes(server.ram_used==null?undefined:server.ram_used*1048576)} / ${bytes(server.ram_total==null?undefined:server.ram_total*1048576)}`"/><MetricBar :label="t('磁盘','Storage')" :value="percent(server.disk_used,server.disk_total)" :caption="`${bytes(server.disk_used==null?undefined:server.disk_used*1048576)} / ${bytes(server.disk_total==null?undefined:server.disk_total*1048576)}`"/></div><div class="network-row"><div><small>↓ {{t('下载','IN')}}</small><b>{{bytes(server.net_in_speed,'/s')}}</b></div><div><small>↑ {{t('上传','OUT')}}</small><b>{{bytes(server.net_out_speed,'/s')}}</b></div></div><div v-if="site.sysConfig.show_tf===true" class="traffic-row muted"><span>{{t('月流量','Monthly traffic')}}</span><b>↓ {{bytes(server.net_rx_monthly)}} · ↑ {{bytes(server.net_tx_monthly)}}</b></div><div v-if="site.sysConfig.show_three_net_details===true && options.showCharts"><SparkChart v-if="Array.isArray(server.ping) && server.ping.length" small :rows="server.ping" :series="lineSeries" unit=" ms"/><SparkChart v-if="Array.isArray(server.loss) && server.loss.length" small :rows="server.loss" :series="lineSeries" unit="%"/></div><div class="card-bottom"><span class="os-label"><img :src="`${site.base}/os-icons/${osFile}`" alt="">{{server.os || '—'}}</span><span v-if="site.sysConfig.show_price===true && cardPrice">{{cardPrice==='free'?t('免费','Free'):cardPrice}}</span><span v-else>{{server.arch || '—'}}</span></div><p v-if="site.sysConfig.show_expire===true && server.expire_date" class="expiry muted">{{t('到期','Expires')}} {{server.expire_date}} · {{server.auto_renewal==='1'?t('自动续费','Auto-renew'):t('手动续费','Manual renew')}}</p></article></template>
